(3, '19fbbc84f257674a', 'thread_6a6d7fa1a97bb_1785560993', 2, 'hardenfaderon@gmail.com', 'hardenfaderon@gmail.com', '[\"edrianfaderon@gmail.com\"]', NULL, NULL, NULL, 'Re: Re: Partnership Opportunity with Armful Media', 'Hi {{influencer_name}},\r\nWe\'re thrilled to have you on board! Welcome to the Armful Media family. ????\r\n\r\n\r\n  Your Exclusive Discount Code:\r\n  {{discount_code}}\r\n  Offer: {{discount_amount}} off\r\n  Valid until: {{valid_until}}\r\n\r\n\r\nYour Affiliate Link:\r\n{{affiliate_link}}\r\n\r\nNext Steps:\r\n\r\n  We\'ll ship your products to:{{shipping_address}}\r\n  Create authentic content that resonates with your audience\r\n  Use #{{brand_hashtag}} and tag us @{{brand_handle}}\r\n\r\n\r\nQuestions? I\'m here to help!\r\n\r\nExcited to create together! ???\r\n\r\nBest,\r\n{{sender_name}}\r\nArmful Media Partnership Team\r\n\r\nP.S. Track your shipment here', 'Hi {{influencer_name}},\r\nWe\'re thrilled to have you on board! Welcome to the Armful Media family. ????\r\n\r\n\r\n  Your Exclusive Discount Code:\r\n  {{discount_code}}\r\n  Offer: {{discount_amount}} off\r\n  Valid until: {{valid_until}}\r\n\r\n\r\nYour Affiliate Link:\r\n{{affiliate_link}}\r\n\r\nNext Steps:\r\n\r\n  We\'ll ship your products to:{{shipping_address}}\r\n  Create authentic content that resonates with your audience\r\n  Use #{{brand_hashtag}} and tag us @{{brand_handle}}\r\n\r\n\r\nQuestions? I\'m here to help!\r\n\r\nExcited to create together! ???\r\n\r\nBest,\r\n{{sender_name}}\r\nArmful Media Partnership Team\r\n\r\nP.S. Track your shipment here', 0, NULL, 'outgoing', 1, 0, 0, 0, 0, 0, 0, NULL, NULL, 0, NULL, '2026-07-31 23:25:05', NULL, '2026-08-01 05:25:05', '2026-08-01 05:25:05'),
(59, '19fdb6c42c23351b', '19fdb6c42c23351b', 7, 'no-reply@accounts.google.com', 'Google', '[\"instroomarmful@gmail.com\"]', NULL, NULL, NULL, 'Security alert', '[image: Google]\r\nYou allowed Instroom access to some of your Google Account data\r\n\r\n\r\ninstroomarmful@gmail.com\r\n\r\nIf you didn\'t allow Instroom access to some of your Google Account data,\r\nsomeone else may be trying to access your Google Account data.\r\n\r\nTake a moment now to check your account activity and secure your account.\r\nCheck activity\r\n<https://accounts.google.com/AccountChooser?Email=instroomarmful@gmail.com&continue=https://myaccount.google.com/alert/nt/1786092731000?rfn%3D127%26rfnc%3D1%26eid%3D-6579858791002787433%26et%3D0>\r\nTo make changes at any time to the access that Instroom has to your data,\r\ngo to your Google Account\r\n<https://accounts.google.com/AccountChooser?Email=instroomarmful@gmail.com&continue=https://myaccount.google.com/connections/overview/AWW5nWQjip2fxPXukRFOHsc7dAeb7CFJzjhSqxEAmEfsy_t4skqxeuM0IN3VNY9bYjRDhYwK7E4lZMLyBvf00L7MrSI?utm_source%3Dsec_alert%26utm_medium%3Demail_notification%26force_all%3Dtrue>\r\nYou can also see security activity at\r\nhttps://myaccount.google.com/notifications\r\nYou received this email to let you know about important changes to your\r\nGoogle Account and services.\r\n© 2026 Google LLC, 1600 Amphitheatre Parkway, Mountain View, CA 94043, USA\r\n', '<!DOCTYPE html><html lang=\"en\"><head><meta name=\"format-detection\" content=\"email=no\"/><meta name=\"format-detection\" content=\"date=no\"/><style nonce=\"eFsRze2eVVXAWcpxOdbVtQ\">.awl a {color: #FFFFFF; text-decoration: none;} .abml a {color: #000000; font-family: Roboto-Medium,Helvetica,Arial,sans-serif; font-weight: bold; text-decoration: none;} .adgl a {color: rgba(0, 0, 0, 0.87); text-decoration: none;} .afal a {color: #b0b0b0; text-decoration: none;} @media screen and (min-width: 600px) {.v2sp {padding: 6px 30px 0px;} .v2rsp {padding: 0px 10px;}} @media screen and (