(1, 1, NULL, 'Initial Outreach', 'First contact with influencer', 'Partnership Opportunity with {{brand_name}}', 'Hi {{influencer_name}},\n\nI hope this email finds you well. My name is {{sender_name}} from {{brand_name}}.\n\nWe\'ve been following your content on {{platform}} and absolutely love your style and engagement with your audience. We believe you\'d be a perfect fit for our brand.\n\nWould you be interested in collaborating with us? I\'d love to discuss potential partnership opportunities and how we can work together.\n\nLooking forward to hearing from you!\n\nBest regards,\n{{sender_name}}\n{{sender_title}}\n{{brand_name}}\n{{contact_email}}\n{{contact_phone}}', '<p>Hi {{influencer_name}},</p>\n<p>I hope this email finds you well. My name is {{sender_name}} from <strong>{{brand_name}}</strong>.</p>\n<p>We\'ve been following your content on {{platform}} and absolutely love your style and engagement with your audience. We believe you\'d be a perfect fit for our brand.</p>\n<p>Would you be interested in collaborating with us? I\'d love to discuss potential partnership opportunities and how we can work together.</p>\n<p>Looking forward to hearing from you!</p>\n<p>Best regards,<br>\n{{sender_name}}<br>\n{{sender_title}}<br>\n<strong>{{brand_name}}</strong><br>\n<a href=\"mailto:{{contact_email}}\">{{contact_email}}</a><br>\n{{contact_phone}}</p>', '[\"influencer_name\", \"platform\", \"brand_name\", \"sender_name\", \"sender_title\", \"contact_email\", \"contact_phone\"]', 'outreach', 1, 0, 0, NULL, '2026-07-20 13:30:31', '2026-07-20 13:30:31'),
(2, 1, NULL, 'Follow-up: No Response', 'Follow up after initial outreach', 'Re: Partnership Opportunity with {{brand_name}}', 'Hi {{influencer_name}},\n\nI hope you\'re doing well. I wanted to follow up on my previous email about a potential collaboration between you and {{brand_name}}.\n\nI understand you receive many partnership requests, but I truly believe our brand aligns well with your content and audience. We\'d love to offer you {{collaboration_details}}.\n\nWould you have 10 minutes this week for a quick call to discuss this further?\n\nLooking forward to your response!\n\nBest,\n{{sender_name}}', '<p>Hi {{influencer_name}},</p>\n<p>I hope you\'re doing well. I wanted to follow up on my previous email about a potential collaboration between you and <strong>{{brand_name}}</strong>.</p>\n<p>I understand you receive many partnership requests, but I truly believe our brand aligns well with your content and audience. We\'d love to offer you {{collaboration_details}}.</p>\n<p>Would you have 10 minutes this week for a quick call to discuss this further?</p>\n<p>Looking forward to your response!</p>\n<p>Best,<br>{{sender_name}}</p>', '[\"influencer_name\", \"brand_name\", \"sender_name\", \"collaboration_details\"]', 'follow_up', 1, 0, 0, NULL, '2026-07-20 13:30:31', '2026-07-20 13:30:31'),
(3, 1, NULL, 'Partnership Confirmed', 'Welcome email after agreement', 'Welcome to {{brand_name}} Family! ????', 'Hi {{influencer_name}},\n\nWe\'re thrilled to have you on board! Welcome to the {{brand_name}} family. ????\n\nWe\'ve created a unique discount code just for your followers:\n\n???? **Discount Code: {{discount_code}}**\n???? **Offer: {{discount_amount}} off**\n???? **Valid until: {{valid_until}}**\n\nYour affiliate link: {{affiliate_link}}\n\nNext steps:\n1. We\'ll be shipping your products to: {{shipping_address}}\n2. Once you receive them, feel free to create authentic content that resonates with your audience\n3. Don\'t forget to use #{{brand_hashtag}} and tag us @{{brand_handle}}\n\nIf you have any questions, I\'m here to help!\n\nExcited to see what we create together! ???\n\nBest,\n{{sender_name}}\n{{brand_name}} Partnership Team\n\nP.S. Track your shipment here: {{tracking_link}}', '<div style=\"font-family: Arial, sans-serif; max-width: 600px;\">\n<h2>Hi {{influencer_name}},</h2>\n<p>We\'re thrilled to have you on board! Welcome to the <strong>{{brand_name}}</strong> family. ????</p>\n\n<div style=\"background: #f8f9fa; padding: 20px; border-radius: 8px; margin: 20px 0;\">\n  <h3>Your Exclusive Discount Code:</h3>\n  <p style=\"font-size: 24px; font-weight: bold; color: #1fae5b;\">{{discount_code}}</p>\n  <p><strong>Offer:</strong> {{discount_amount}} off</p>\n  <p><strong>Valid until:</strong> {{valid_until}}</p>\n</div>\n\n<p><strong>Your Affiliate Link:</strong><br>\n<a href=\"{{affiliate_link}}\" style=\"color: #1fae5b;\">{{affiliate_link}}</a></p>\n\n<h3>Next Steps:</h3>\n<ol>\n  <li>We\'ll ship your products to:<br>{{shipping_address}}</li>\n  <li>Create authentic content that resonates with your audience</li>\n  <li>Use <strong>#{{brand_hashtag}}</strong> and tag us <strong>@{{brand_handle}}</strong></li>\n</ol>\n\n<p>Questions? I\'m here to help!</p>\n\n<p>Excited to create together! ???</p>\n\n<p>Best,<br>\n<strong>{{sender_name}}</strong><br>\n{{brand_name}} Partnership Team</p>\n\n<p style=\"font-size: 12px; color: #666;\">P.S. <a href=\"{{tracking_link}}\">Track your shipment here</a></p>\n</div>', '[\"influencer_name\", \"brand_name\", \"sender_name\", \"discount_code\", \"discount_amount\", \"valid_until\", \"affiliate_link\", \"shipping_address\", \"brand_hashtag\", \"brand_handle\", \"tracking_link\"]', 'onboarding', 1, 0, 0, NULL, '2026-07-20 13:30:31', '2026-07-20 13:30:31');

